        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug was the use of outdated functions (`virNetDevReplaceNetConfig()` and `virNetDevReplaceMacAddress()`) that only saved and restored the admin MAC address and VLAN tag, which was incorrect. This led to improper handling of the VF's own MAC address and VLAN tag during the macvtap passthrough setup and teardown processes. The new functions (`virNetDevSaveNetConfig()` and `virNetDevSetNetConfig()`) correctly manage the VF's configuration, thus fixing the bug.

        Commit message:
        util: use new virNetDev*NetConfig() functions for macvtap
 setup/teardown

This patch modifies the macvtap passthrough setup to use
virNetDevSaveNetConfig()+virNetDevSetConfig() instead of
virNetDevReplaceNetConfig() or virNetDevReplaceMacAddress(), and the
teardown to use virNetDevReadNetConfig()+virNetDevSetConfig() instead
of virNetDevRestoreNetConfig() or virNetDevRestoreMacAddress().

Since the older functions only saved/restored the admin MAC and vlan
tag (which is incorrect) and the new functions save/restore the VF's
own MAC address and vlan tag (correct), this actually fixes a bug
(which was introduced by commit cb3fe38c7, which was itself supposed
to be a fix for https://bugzilla.redhat.com/1113474 ).

The downside to this patch is that it causes an *apparent* regression
in that bug (because there will once again be an error reported if the
interface had previously been used for VFIO device assignment), but in
reality, the code hasn't been working for *any* case before this
current patch (at least not with any recent kernel). Anyway, that
"regression" will be fixed with an upcoming patch that fixes it the
*right* way.  

        Patch:
          */
 int
 virNetDevMacVLanCreateWithVPortProfile(const char *ifnameRequested,
                                        const virMacAddr *macaddress,
                                        const char *linkdev,
                                        virNetDevMacVLanMode mode,
                                        virNetDevVlanPtr vlan,
                                        const unsigned char *vmuuid,
                                        virNetDevVPortProfilePtr virtPortProfile,
                                        char **ifnameResult,
                                        virNetDevVPortProfileOp vmOp,
                                        char *stateDir,
                                        int *tapfd,
                                        size_t tapfdSize,
                                        unsigned int flags)
 {
     const char *type = (flags & VIR_NETDEV_MACVLAN_CREATE_WITH_TAP) ?
         MACVTAP_NAME_PREFIX : MACVLAN_NAME_PREFIX;
     const char *pattern = (flags & VIR_NETDEV_MACVLAN_CREATE_WITH_TAP) ?
         MACVTAP_NAME_PATTERN : MACVLAN_NAME_PATTERN;
     int reservedID = -1;
     char ifname[IFNAMSIZ];
     int retries, do_retry = 0;
     uint32_t macvtapMode;
     const char *ifnameCreated = NULL;
     int vf = -1;
     bool vnet_hdr = flags & VIR_NETDEV_MACVLAN_VNET_HDR;

     macvtapMode = modeMap[mode];

     *ifnameResult = NULL;

     /** Note: When using PASSTHROUGH mode with MACVTAP devices the link
      * device's MAC address must be set to the VMs MAC address. In
      * order to not confuse the first switch or bridge in line this MAC
      * address must be reset when the VM is shut down.
      * This is especially important when using SRIOV capable cards that
      * emulate their switch in firmware.
      */

     if (mode == VIR_NETDEV_MACVLAN_MODE_PASSTHRU) {
+        bool setVlan = true;
+
         if (virtPortProfile &&
             virtPortProfile->virtPortType == VIR_NETDEV_VPORT_PROFILE_8021QBH) {
-            /* The Cisco enic driver (the only card that uses
-             * 802.1Qbh) doesn't support IFLA_VFINFO_LIST, which is
-             * required for virNetDevReplaceNetConfig(), so we must
-             * use this function (which uses ioctl(SIOCGIFHWADDR)
-             * instead or virNetDevReplaceNetConfig()
+            /* The Cisco enic driver (the only SRIOV-capable card that
+             * uses 802.1Qbh) doesn't support IFLA_VFINFO_LIST, which
+             * is required to get/set the vlan tag of a VF.
              */
-            if (virNetDevReplaceMacAddress(linkdev, macaddress, stateDir) < 0)
-                return -1;
-        } else {
-            if (virNetDevReplaceNetConfig(linkdev, -1, macaddress, vlan, stateDir) < 0)
-                return -1;
+            setVlan = false;
         }
+
+        if (virNetDevSaveNetConfig(linkdev, -1, stateDir, setVlan) < 0)
+           return -1;
+
+        if (virNetDevSetNetConfig(linkdev, -1, NULL, vlan, macaddress, setVlan) < 0)
+           return -1;
     }

     if (ifnameRequested) {
         int rc;
         bool isAutoName
             = (STRPREFIX(ifnameRequested, MACVTAP_NAME_PREFIX) ||
                STRPREFIX(ifnameRequested, MACVLAN_NAME_PREFIX));

         VIR_INFO("Requested macvtap device name: %s", ifnameRequested);
         virMutexLock(&virNetDevMacVLanCreateMutex);

         if ((rc = virNetDevExists(ifnameRequested)) < 0) {
             virMutexUnlock(&virNetDevMacVLanCreateMutex);
             return -1;
         }
         if (rc) {
             if (isAutoName)
                 goto create_name;
             virReportSystemError(EEXIST,
                                  _("Unable to create %s device %s"),
                                  type, ifnameRequested);
             virMutexUnlock(&virNetDevMacVLanCreateMutex);
             return -1;
         }
         if (isAutoName &&
             (reservedID = virNetDevMacVLanReserveName(ifnameRequested, true)) < 0) {
             reservedID = -1;
             goto create_name;
         }

         if (virNetDevMacVLanCreate(ifnameRequested, type, macaddress,
                                    linkdev, macvtapMode, &do_retry) < 0) {
             if (isAutoName) {
                 virNetDevMacVLanReleaseName(ifnameRequested);
                 reservedID = -1;
                 goto create_name;
             }
             virMutexUnlock(&virNetDevMacVLanCreateMutex);
             return -1;
         }
         /* virNetDevMacVLanCreate() was successful - use this name */
         ifnameCreated = ifnameRequested;
  create_name:
         virMutexUnlock(&virNetDevMacVLanCreateMutex);
     }

     retries = MACVLAN_MAX_ID;
     while (!ifnameCreated && retries) {
         virMutexLock(&virNetDevMacVLanCreateMutex);
         reservedID = virNetDevMacVLanReserveID(reservedID, flags, false, true);
         if (reservedID < 0) {
             virMutexUnlock(&virNetDevMacVLanCreateMutex);
             return -1;
         }
         snprintf(ifname, sizeof(ifname), pattern, reservedID);
         if (virNetDevMacVLanCreate(ifname, type, macaddress, linkdev,
                                    macvtapMode, &do_retry) < 0) {
             virNetDevMacVLanReleaseID(reservedID, flags);
             virMutexUnlock(&virNetDevMacVLanCreateMutex);
             if (!do_retry)
                 return -1;
             VIR_INFO("Device %s wasn't reserved but already existed, skipping",
                      ifname);
             retries--;
             continue;
         }
         ifnameCreated = ifname;
         virMutexUnlock(&virNetDevMacVLanCreateMutex);
     }

     if (!ifnameCreated) {
         virReportError(VIR_ERR_INTERNAL_ERROR,
                        _("Too many unreserved %s devices in use"),
                        type);
         return -1;
     }

     if (virNetDevVPortProfileAssociate(ifnameCreated,
                                        virtPortProfile,
                                        macaddress,
                                        linkdev,
                                        vf,
                                        vmuuid, vmOp, false) < 0)
         goto link_del_exit;

     if (flags & VIR_NETDEV_MACVLAN_CREATE_IFUP) {
         if (virNetDevSetOnline(ifnameCreated, true) < 0)
             goto disassociate_exit;
     }

     if (flags & VIR_NETDEV_MACVLAN_CREATE_WITH_TAP) {
         if (virNetDevMacVLanTapOpen(ifnameCreated, tapfd, tapfdSize, 10) < 0)
             goto disassociate_exit;

         if (virNetDevMacVLanTapSetup(tapfd, tapfdSize, vnet_hdr) < 0)
             goto disassociate_exit;

         if (VIR_STRDUP(*ifnameResult, ifnameCreated) < 0)
             goto disassociate_exit;
     } else {
         if (VIR_STRDUP(*ifnameResult, ifnameCreated) < 0)
             goto disassociate_exit;
     }

     if (vmOp == VIR_NETDEV_VPORT_PROFILE_OP_CREATE ||
         vmOp == VIR_NETDEV_VPORT_PROFILE_OP_RESTORE) {
         /* Only directly register upon a create or restore (restarting
          * a saved image) - migration and libvirtd restart are handled
          * elsewhere.
          */
         if (virNetDevMacVLanVPortProfileRegisterCallback(ifnameCreated, macaddress,
                                                          linkdev, vmuuid,
                                                          virtPortProfile,
                                                          vmOp) < 0)
             goto disassociate_exit;
     }

     return 0;

  disassociate_exit:
     ignore_value(virNetDevVPortProfileDisassociate(ifnameCreated,
                                                    virtPortProfile,
                                                    macaddress,
                                                    linkdev,
                                                    vf,
                                                    vmOp));
     while (tapfdSize--)
         VIR_FORCE_CLOSE(tapfd[tapfdSize]);

  link_del_exit:
     ignore_value(virNetDevMacVLanDelete(ifnameCreated));
     virNetDevMacVLanReleaseName(ifnameCreated);

     return -1;
 }

  */
 int virNetDevMacVLanDeleteWithVPortProfile(const char *ifname,
                                            const virMacAddr *macaddr,
                                            const char *linkdev,
                                            int mode,
                                            virNetDevVPortProfilePtr virtPortProfile,
                                            char *stateDir)
 {
     int ret = 0;

     if (ifname) {
         if (virNetDevVPortProfileDisassociate(ifname,
                                               virtPortProfile,
                                               macaddr,
                                               linkdev,
                                               -1,
                                               VIR_NETDEV_VPORT_PROFILE_OP_DESTROY) < 0)
             ret = -1;
         if (virNetDevMacVLanDelete(ifname) < 0)
             ret = -1;
         virNetDevMacVLanReleaseName(ifname);
     }

     if (mode == VIR_NETDEV_MACVLAN_MODE_PASSTHRU) {
-        if (virtPortProfile &&
-             virtPortProfile->virtPortType == VIR_NETDEV_VPORT_PROFILE_8021QBH)
-            ignore_value(virNetDevRestoreMacAddress(linkdev, stateDir));
-        else
-            ignore_value(virNetDevRestoreNetConfig(linkdev, -1, stateDir));
+        virMacAddrPtr MAC = NULL;
+        virMacAddrPtr adminMAC = NULL;
+        virNetDevVlanPtr vlan = NULL;
+
+        if (virNetDevReadNetConfig(linkdev, -1, stateDir,
+                                   &adminMAC, &vlan, &MAC) == 0) {
+
+            ignore_value(virNetDevSetNetConfig(linkdev, -1,
+                                               adminMAC, vlan, MAC, !!vlan));
+            VIR_FREE(MAC);
+            VIR_FREE(adminMAC);
+            virNetDevVlanFree(vlan);
+        }
     }

     virNetlinkEventRemoveClient(0, macaddr, NETLINK_ROUTE);

     return ret;
 }



